import * as T from 'three';
import {QUALITY_PROFILES} from './performance.mjs?v=0.5.0';

export class Effects{
 clear(){
  this.life.fill(0);this.p.fill(-1000);this.points.geometry.attributes.position.needsUpdate=true;
  for(const r of this.rings){r.age=-1;r.m.visible=false;}
  for(const item of this.lines){item.age=-1;item.line.visible=false;}this.points.geometry.setDrawRange(0,0);
  this.lightAge.fill(0);for(const light of this.lights)light.intensity=0;
 }
 constructor(scene,city,intensity){this.scene=scene;this.city=city;this.intensity=intensity;this.cursor=0;this.N=3000;this.life=new Float32Array(this.N);this.age=new Float32Array(this.N);this.p=new Float32Array(this.N*3);this.vel=new Float32Array(this.N*3);this.base=new Float32Array(this.N*3);this.color=new Float32Array(this.N*3);this.p.fill(-1000);const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(this.p,3));g.setAttribute('color',new T.BufferAttribute(this.color,3));const c=document.createElement('canvas');c.width=c.height=32;const q=c.getContext('2d'),a=q.createRadialGradient(16,16,0,16,16,16);a.addColorStop(0,'white');a.addColorStop(.18,'#ffffffe0');a.addColorStop(1,'#ffffff00');q.fillStyle=a;q.fillRect(0,0,32,32);this.points=new T.Points(g,new T.PointsMaterial({size:.13,map:new T.CanvasTexture(c),vertexColors:true,transparent:true,blending:T.AdditiveBlending,depthWrite:false}));this.points.frustumCulled=false;scene.add(this.points);this.lightAge=new Float32Array(4);this.lights=Array.from({length:4},()=>{const l=new T.PointLight(0xff2fa2,0,5,2);scene.add(l);return l;});this.rings=Array.from({length:40},()=>{const m=new T.Mesh(new T.TorusGeometry(1,.025,4,48),new T.MeshBasicMaterial({color:0xffffff,transparent:true,depthWrite:false,blending:T.AdditiveBlending}));m.rotation.x=Math.PI/2;m.visible=false;scene.add(m);return{m,age:-1,size:1};});this.lines=Array.from({length:48},()=>{const g=new T.BufferGeometry(),vertices=new Float32Array(129*3);g.setAttribute('position',new T.BufferAttribute(vertices,3).setUsage(T.DynamicDrawUsage));g.setDrawRange(0,0);const line=new T.Line(g,new T.LineBasicMaterial({transparent:true,blending:T.AdditiveBlending}));line.frustumCulled=false;line.visible=false;scene.add(line);return{line,vertices,age:-1};});this.flash=0;this.setQuality('low');}
 setQuality(quality){this.quality=QUALITY_PROFILES[quality]??QUALITY_PROFILES.low;this.clear();for(let i=0;i<this.lights.length;i++)this.lights[i].visible=i<this.quality.flashes;}
 sparks(pos,color,count=28,strength=1,velocity=null){const rgb=new T.Color(color);for(let j=0;j<Math.round(count*this.intensity);j++){const i=this.cursor++%this.quality.particles,k=i*3;this.p[k]=pos.x;this.p[k+1]=pos.y+.25;this.p[k+2]=pos.z;const a=Math.random()*Math.PI*2,s=(1+Math.random()*4)*strength;this.vel[k]=Math.cos(a)*s+(velocity?.x??0)*.05;this.vel[k+1]=(1+Math.random()*4)*strength;this.vel[k+2]=Math.sin(a)*s+(velocity?.z??0)*.05;this.age[i]=0;this.life[i]=.25+Math.random()*.65;this.base[k]=rgb.r;this.base[k+1]=rgb.g;this.base[k+2]=rgb.b;}}
 ring(pos,color,size=1,danger=false){const candidates=this.rings.filter((x,i)=>danger?i>=28:i<(this.quality.bloom?28:16));const r=candidates.find(x=>x.age<0)??(danger?candidates.reduce((a,b)=>a.age>b.age?a:b):null);if(!r)return;r.age=0;r.size=size;r.m.position.copy(pos);r.m.position.y+=.08;r.m.material.color.set(color);r.m.visible=true;}
 impact(pos,color,major=false){this.sparks(pos,color,major?110:32,major?1.25:1);this.ring(pos,color,major?2.5:.65);if(!this.quality.flashes)return;const i=this.flash++%this.quality.flashes;this.lights[i].position.copy(pos);this.lights[i].position.y+=.6;this.lights[i].color.set(color);this.lightAge[i]=.16;}
 arc(a,b,color,branches=3){const entry=this.lines.find(x=>x.age<0);if(!entry)return;const n=Math.min(128,Math.max(7,Math.ceil(a.distanceTo(b)*4))),p=entry.vertices;for(let i=0;i<=n;i++){const t=i/n,j=i*3,v=Math.sin(t*Math.PI);p[j]=a.x+(b.x-a.x)*t+(Math.random()-.5)*.48*v;p[j+1]=a.y+(b.y-a.y)*t+((Math.random()-.5)*.4+.5)*v;p[j+2]=a.z+(b.z-a.z)*t+(Math.random()-.5)*.48*v;}entry.age=0;entry.line.visible=true;entry.line.material.color.set(color);entry.line.material.opacity=1;entry.line.geometry.attributes.position.needsUpdate=true;entry.line.geometry.setDrawRange(0,n+1);for(let i=0;i<Math.min(branches,this.quality.bloom?3:1);i++){const j=(2+Math.floor(Math.random()*(n-3)))*3,start=new T.Vector3().fromArray(p,j);this.arc(start,start.clone().add(new T.Vector3((Math.random()-.5)*1.5,Math.random(),(Math.random()-.5)*1.5)),color,0);}}

 tick(dt){let end=0;for(let i=0;i<this.quality.particles;i++){if(this.life[i]<=0)continue;const k=i*3;this.age[i]+=dt;if(this.age[i]>=this.life[i]){this.life[i]=0;this.p[k+1]=-1000;continue;}end=i+1;const oldX=this.p[k],oldZ=this.p[k+2];this.vel[k+1]-=dt*12;this.p[k]+=this.vel[k]*dt;this.p[k+1]+=this.vel[k+1]*dt;this.p[k+2]+=this.vel[k+2]*dt;const floor=this.city.height(this.p[k],this.p[k+2],this.p[k+1])+.045;if(this.p[k+1]<floor){this.p[k+1]=floor;this.vel[k+1]=Math.abs(this.vel[k+1])*.38;this.vel[k]*=.75;this.vel[k+2]*=.75;}if(this.city.blocked(this.p[k],this.p[k+2],0,this.p[k+1])){this.p[k]=oldX;this.p[k+2]=oldZ;this.vel[k]*=-.5;this.vel[k+2]*=-.5;}const fade=(1-this.age[i]/this.life[i])*1.8;for(let c=0;c<3;c++)this.color[k+c]=this.base[k+c]*fade;}this.points.geometry.setDrawRange(0,end);if(end){this.points.geometry.attributes.position.needsUpdate=true;this.points.geometry.attributes.color.needsUpdate=true;}for(let i=0;i<this.quality.flashes;i++){this.lightAge[i]=Math.max(0,this.lightAge[i]-dt);this.lights[i].intensity=20*this.lightAge[i]/.16*(this.userFlash??1);}for(const r of this.rings)if(r.age>=0){r.age+=dt;r.m.scale.setScalar(Math.max(.01,r.age/.4*r.size));r.m.material.opacity=Math.max(0,1-r.age/.4);if(r.age>.4){r.age=-1;r.m.visible=false;}}for(const a of this.lines)if(a.age>=0){a.age+=dt;a.line.material.opacity=Math.max(0,1-a.age/.2);if(a.age>.2){a.age=-1;a.line.visible=false;}}}
}
